<?php
namespace App\Interfaces\Http\Controllers\Api\V1\Customers;use App\Application\Customers\PartyService;use App\Models\Party;use Illuminate\Http\JsonResponse;use Illuminate\Http\Request;
final class PartyController{public function index(Request$r):JsonResponse{$q=Party::with(['contacts','identifiers']);if(!$this->global($r))$q->whereHas('customers',fn($x)=>$x->where('tenant_id',app(\App\Domain\Tenancy\TenantContext::class)->id()));if($r->filled('search'))$q->where('display_name','ilike','%'.str_replace(['%','_'],['\%','\_'],$r->string('search')).'%');return response()->json(['data'=>$q->orderBy('display_name')->paginate(min($r->integer('per_page',25),100))]);}public function store(Request$r,PartyService$s):JsonResponse{$d=$r->validate(['type'=>'required|in:PERSON,ORGANIZATION','display_name'=>'required|string|max:160','phone_e164'=>['nullable','regex:/^\+[1-9]\d{7,14}$/'],'email'=>'nullable|email|max:190','date_of_birth'=>'nullable|date|before:-18 years','registration_number'=>'nullable|string|max:100','identifier_type'=>'nullable|required_with:identifier_value|in:NATIONAL_ID,PASSPORT,RCCM','identifier_value'=>'nullable|required_with:identifier_type|string|max:100','identifier_country'=>'nullable|string|size:2']);return response()->json(['data'=>$s->create($d)->load('contacts','identifiers')],201);}public function show(Request$r,Party$party):JsonResponse{abort_unless($this->global($r)||$party->customers()->where('tenant_id',app(\App\Domain\Tenancy\TenantContext::class)->id())->exists(),404);return response()->json(['data'=>$party->load('contacts','identifiers','customers.tenant','consents','attributions.partner.party')]);}private function global(Request$r):bool{return$r->user()->memberships()->where('status','ACTIVE')->whereIn('role_code',['SYSTEM_ADMIN','PLATFORM_ADMIN','COMPLIANCE_ADMIN'])->exists();}}
